powerpagecomponent.content:
{
  "source": "{%- comment -%}
  Donate/Payment Web Template (DROP-IN)

  URL:
    /Donate/Payment/?acceptanceid=<guid>&token=<clientToken>

  - Fetch Offering Acceptance by ID
  - Validate token matches acceptance hit_clienttoken (prevents URL tampering)
  - Fetch Offering by lookup
  - Calls Flow A to create/reuse Stripe PaymentIntent -> returns clientSecret
  - Renders Stripe Payment Element
  - Confirms payment and redirects to /Donate/Complete with absolute return_url
{%- endcomment -%}

{%- assign flow_pi_url  = settings['Flow/PaymentIntentUrl']  | default: '' -%}
{%- assign flow_si_url  = settings['Flow/SetupIntentUrl']    | default: '' -%}
{%- assign stripe_pk = settings['Stripe/PublishableKey'] | default: '' -%}
{%- assign acceptanceid = request.params['acceptanceid'] | default: '' | strip -%}
{%- assign token = request.params['token'] | default: '' | strip -%}

{%- assign acceptance = nil -%}
{%- assign offering = nil -%}
{%- assign offeringid = '' -%}

{%- if acceptanceid != blank -%}
  {%- fetchxml acceptance_q -%}
  <fetch top="1" mapping="logical" distinct="false">
    <entity name="hit_offeringacceptance">
      <attribute name="hit_offeringacceptanceid" />
      <attribute name="hit_name" />
      <attribute name="hit_baseamount" />
      <attribute name="hit_totalamount" />
      <attribute name="hit_donationaddonamount" />
      <attribute name="hit_clienttoken" />
      <attribute name="hit_email" />
      <attribute name="hit_issubscription" />
      <attribute name="hit_offering" />
      <filter type="and">
        <condition attribute="hit_offeringacceptanceid" operator="eq" value="{{ acceptanceid | escape }}" />
      </filter>
    </entity>
  </fetch>
  {%- endfetchxml -%}

  {%- assign acceptance = acceptance_q.results.entities | first -%}
{%- endif -%}

{%- if acceptance and acceptance.hit_offering -%}
  {%- assign offeringid = acceptance.hit_offering.id | default: acceptance.hit_offering.Id | default: acceptance.hit_offering.guid | default: acceptance.hit_offering -%}
  {%- assign offeringid = offeringid | strip -%}

  {%- assign is_subscription = false -%}
  {%- assign is_sub_raw = acceptance.hit_issubscription | downcase | strip -%}
  {%- if is_sub_raw == 'true' or is_sub_raw == '1' or is_sub_raw == 'yes' -%}
    {%- assign is_subscription = true -%}
  {%- endif -%}  
{%- endif -%}

{%- if offeringid != blank -%}
  {%- fetchxml offering_q -%}
  <fetch top="1" mapping="logical" distinct="false">
    <entity name="hit_offering">
      <attribute name="hit_offeringid" />
      <attribute name="hit_offeringname" />
      <attribute name="hit_slug" />
      <attribute name="hit_isactive" />
      <attribute name="hit_allowrecurring" />
      <attribute name="hit_imageurl" /> 

      <attribute name="hit_subscriptionfrequency" />
      <attribute name="hit_pricingmodel" />

      <filter type="and">
        <condition attribute="hit_offeringid" operator="eq" value="{{ offeringid | escape }}" />
      </filter>
    </entity>
  </fetch>
  {%- endfetchxml -%}

  {%- assign offering = offering_q.results.entities | first -%}
{%- endif -%}

{%- assign offering_name = offering.hit_offeringname | default: 'Donation' -%}
{%- assign offering_slug = offering.hit_slug | default: '' -%}
{%- assign offering_image = offering.hit_imageurl | default: '' | strip -%}
{%- assign allow_recurring = false -%}
{%- if offering.hit_allowrecurring == true or offering.hit_allowrecurring == 1 -%}
  {%- assign allow_recurring = true -%}
{%- endif -%}

{%- assign acceptance_token = acceptance.hit_clienttoken | default: '' | strip -%}

{%- assign sub_freq_label = '' -%}
{%- if offering.hit_subscriptionfrequency -%}
  {%- if offering.hit_subscriptionfrequency.label -%}
    {%- assign sub_freq_label = offering.hit_subscriptionfrequency.label -%}
  {%- else -%}
    {%- assign sub_freq_label = offering['hit_subscriptionfrequency@OData.Community.Display.V1.FormattedValue'] | default: '' -%}
  {%- endif -%}
{%- endif -%}

<style>
  .wrap{
    max-width: 1180px;
    margin: 0 auto;
    padding: 28px 16px 84px;
    font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
    color: #0f172a;
  }
  .alert{
    border: 1px solid rgba(220, 38, 38, 0.25);
    background: rgba(220, 38, 38, 0.06);
    color: #7f1d1d;
    border-radius: 16px;
    padding: 14px 16px;
  }
  .muted{ color: rgba(15, 23, 42, 0.7); }

  .card{
    background: #fff;
    border: 1px solid rgba(15,23,42,.08);
    border-radius: 26px;
    overflow: hidden;
    box-shadow: 0 16px 40px rgba(15,23,42,.10);
  }
  .header{
    padding: 22px 26px;
    border-bottom: 1px solid rgba(15,23,42,.08);
    background: linear-gradient(to bottom, rgba(15,23,42,.02), rgba(15,23,42,0));
  }
  .title{
    margin: 0;
    font-size: clamp(24px, 3vw, 34px);
    line-height: 1.1;
    letter-spacing: -0.02em;
  }
  .sub{
    margin: 10px 0 0;
    color: rgba(15,23,42,.72);
    line-height: 1.55;
    max-width: 70ch;
  }
  .body{ padding: 20px 26px 28px; }

  .grid{
    display: grid;
    grid-template-columns: 1fr;
    gap: 18px;
    align-items: start;
  }
  @media (min-width: 960px){
    .grid{ grid-template-columns: 0.95fr 1.05fr; }
  }

  .panel{
    border: 1px solid rgba(15,23,42,.10);
    border-radius: 20px;
    padding: 16px;
    background: rgba(15,23,42,.02);
  }
  .panel.white{ background: #fff; }

  .sum-row{
    display: flex;
    justify-content: space-between;
    gap: 16px;
    margin: 10px 0;
  }
  .sum-label{
    color: rgba(15,23,42,.70);
    font-size: 13px;
  }
  .sum-val{
    font-weight: 900;
    text-align: right;
    max-width: 60%;
    word-break: break-word;
  }

  .note{
    margin-top: 12px;
    font-size: 12.5px;
    color: rgba(15,23,42,.65);
    line-height: 1.45;
  }

  .pill{
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 10px;
    border-radius: 999px;
    border: 1px solid rgba(15,23,42,.10);
    background: #fff;
    font-size: 12.5px;
    color: rgba(15,23,42,.75);
    margin-top: 10px;
  }
  .dot{
    width: 10px;
    height: 10px;
    border-radius: 999px;
    background: rgba(15,23,42,.25);
  }
  .dot.ok{ background: rgba(16,185,129,.9); }
  .dot.busy{ background: rgba(59,130,246,.9); }

  .err{
    margin-top: 10px;
    color: #7f1d1d;
    background: rgba(220,38,38,.06);
    border: 1px solid rgba(220,38,38,.25);
    padding: 10px 12px;
    border-radius: 14px;
    display: none;
    white-space: pre-wrap;
  }

  #payment-element{ margin-top: 14px; }

  .cta{
    margin-top: 16px;
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    align-items: center;
  }

  .btn{
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 12px 18px;
    border-radius: 999px;
    border: 1px solid rgba(15,23,42,.12);
    background: #0f172a;
    color: #fff;
    text-decoration: none;
    font-weight: 850;
    cursor: pointer;
    transition: transform .08s ease, opacity .12s ease;
  }
  .btn:hover{ opacity: .92; transform: translateY(-1px); }
  .btn.secondary{ background: #fff; color: #0f172a; }
  .btn:disabled{ opacity: .55; cursor: not-allowed; transform: none; }
</style>

<div class="wrap">

  {%- if acceptanceid == blank -%}
    <div class="alert">
      <strong>Missing acceptance id.</strong>
      <div class="muted" style="margin-top:6px;">Please restart your donation from the offering page.</div>
    </div>

  {%- elsif token == blank -%}
    <div class="alert">
      <strong>Missing payment token.</strong>
      <div class="muted" style="margin-top:6px;">Please restart your donation from the offering page.</div>
    </div>

  {%- elsif acceptance == nil -%}
    <div class="alert">
      <strong>Payment session not found.</strong>
      <div class="muted" style="margin-top:6px;">Please restart your donation from the offering page.</div>
    </div>

  {%- elsif acceptance_token != '' and acceptance_token != token -%}
    <div class="alert">
      <strong>Payment session mismatch.</strong>
      <div class="muted" style="margin-top:6px;">
        This payment link is not valid for the current session. Please restart your donation from the offering page.
      </div>
    </div>

  {%- else -%}

    {%- assign email = acceptance.hit_email | default: '' -%}
    {%- assign total = acceptance.hit_totalamount | default: '' -%}
    {%- assign baseamt = acceptance.hit_baseamount | default: '' -%}
    {%- assign addonamt = acceptance.hit_donationaddonamount | default: '' -%}

    <div class="card">

      {%- if offering_image != blank -%}
        <div class="heroimg">
          {%- if offering_image contains '<img' -%}
            {{ offering_image }}
          {%- else -%}
            <img src="{{ offering_image | escape }}" alt="{{ offering_name | escape }}" loading="lazy" />
          {%- endif -%}
        </div>
      {%- endif -%}

      <div class="header">
        <h1 class="title">Secure payment</h1>
        <div class="sub">Complete your donation securely. If verification is required (3‑D Secure), you may be prompted to approve it.</div>
      </div>

      <div class="body">
        <div class="grid">

          <!-- Summary -->
          <div class="panel">
            <div class="sum-row">
              <div class="sum-label">Offering</div>
              <div class="sum-val">{{ offering_name | escape }}</div>
            </div>

            <div class="sum-row">
              <div class="sum-label">Amount</div>
              <div class="sum-val" id="amountDisplay">—</div>
            </div>

            {%- if is_subscription -%}
              <div class="sum-row">
                <div class="sum-label">Billing</div>
                <div class="sum-val">
                  {{ sub_freq_label | default: 'Monthly' | escape }}
                  <div style="color:rgba(15,23,42,.6);font-size:.88em;font-weight:400;margin-top:2px;">
                    Recurring • AUD
                  </div>
                </div>
              </div>
            {%- else -%}
              <div class="sum-row">
                <div class="sum-label">Type</div>
                <div class="sum-val">One-off payment</div>
              </div>
            {%- endif -%}

            {%- if email != blank -%}
              <div class="sum-row">
                <div class="sum-label">Receipt email</div>
                <div class="sum-val">{{ email | escape }}</div>
              </div>
            {%- endif -%}

            <div class="note">Powered by Stripe. Your card details are not stored in this site.</div>
          </div>

          <!-- Payment -->
          <div class="panel white">
            <div style="font-weight:900; font-size:16px;">Payment details</div>
            <div class="muted" style="font-size:13px;margin-top:4px;">Enter your details to complete payment.</div>

            <div class="pill" aria-live="polite">
              <span id="statusDot" class="dot busy"></span>
              <span id="statusText">Loading secure payment…</span>
            </div>

            <div class="err" id="errBox"></div>

            {% if allow_recurring %}
              <div class="recurring-box">
                <label class="check-row">
                  <input type="checkbox" id="enableRecurring" />
                  <strong>Create a recurring payment schedule</strong>
                </label>

                <div id="recurringFields" style="display:none;margin-top:12px;">
                  <div class="field">
                    <label>Frequency</label>
                    <select id="recurringFrequency">
                      <option value="monthly">Monthly</option>
                      <option value="quarterly">Quarterly</option>
                      <option value="yearly">Yearly</option>
                    </select>
                  </div>

                  <div class="field">
                    <label>Start date</label>
                    <input type="date" id="recurringStartDate" />
                  </div>

                  <div class="field">
                    <label>End date (optional)</label>
                    <input type="date" id="recurringEndDate" />
                  </div>

                  <div class="note">
                    Your payment method will be securely stored for scheduled payments.
                    You can cancel at any time.
                  </div>
                </div>
              </div>
            {% endif %}


            <div id="payment-element"></div>

            <div class="cta">
              <button class="btn" id="payBtn" disabled>Pay now</button>
              <a class="btn secondary" href="/Donate/?offeringid={{ offeringid | escape }}&amount={{ baseamt }}{% if offering_slug != '' %}&slug={{ offering_slug | escape }}{% endif %}">
                Back
              </a>
            </div>

            <div class="note">
              {%- if is_subscription -%}
                After you set up your payment method, your membership will be activated. You can cancel at any time.
              {%- else -%}
                After you confirm payment, you'll be redirected to confirm your order.
              {%- endif -%}
            </div>

            <!-- Hidden context -->
            <input type="hidden" id="acceptanceId" value="{{ acceptanceid | escape }}">
            <input type="hidden" id="clientToken" value="{{ token | escape }}">
            <input type="hidden" id="totalAmount" value="{{ total }}">
            <input type="hidden" id="baseAmount" value="{{ baseamt }}">
            <input type="hidden" id="addonAmount" value="{{ addonamt }}">
            <input type="hidden" id="isSubscription"   value="{{ is_subscription }}">
            <input type="hidden" id="subFreqLabel"     value="{{ sub_freq_label | escape }}">
          </div>

        </div>
      </div>
    </div>

<script src="https://js.stripe.com/v3/"></script>

<script>
(function () {

  // ============================
  // CONFIG
  // ============================
  var FLOW_SETUPINTENT_URL   = "{{ flow_si_url  | strip }}";
  var FLOW_PAYMENTINTENT_URL = "{{ flow_pi_url  | strip }}";
  var STRIPE_PUBLISHABLE_KEY = "{{ stripe_pk    | strip }}";

  var COMPLETE_URL = "/Donate/Complete";

  // ============================
  // DOM
  // ============================
  var payBtn = document.getElementById("payBtn");
  var errBox = document.getElementById("errBox");
  var statusText = document.getElementById("statusText");
  var statusDot = document.getElementById("statusDot");
  var paymentMount = document.getElementById("payment-element");

  var acceptanceId = (document.getElementById("acceptanceId") || {}).value || "";
  var clientToken  = (document.getElementById("clientToken")  || {}).value || "";

  var enableRecurring = document.getElementById("enableRecurring");
  var recurringFields = document.getElementById("recurringFields");

  // Amount hidden inputs (optional but recommended)
  var totalEl = document.getElementById("totalAmount");
  var baseEl  = document.getElementById("baseAmount");
  var addEl   = document.getElementById("addonAmount");
  var amountDisplay = document.getElementById("amountDisplay");

  // Recurring inputs (may not exist if recurring disabled)
  var freqEl  = document.getElementById("recurringFrequency");
  var startEl = document.getElementById("recurringStartDate");
  var endEl   = document.getElementById("recurringEndDate");

  // Subscription detection
  var isSubscription = (document.getElementById('isSubscription')?.value || '').toLowerCase() === 'true';
  var subFreqLabel   = document.getElementById('subFreqLabel')?.value || 'Monthly';

  // ============================
  // UI HELPERS
  // ============================
  function showError(msg){
    errBox.style.display = "block";
    errBox.textContent = msg;
  }
  function clearError(){
    errBox.style.display = "none";
    errBox.textContent = "";
  }
  function setStatus(text, state){
    statusText.textContent = text;
    statusDot.classList.remove("ok","busy");
    if (state === "ok") statusDot.classList.add("ok");
    if (state === "busy") statusDot.classList.add("busy");
  }

  // ============================
  // Amount display helpers
  // ============================
  function cleanNumber(v){
    var val = (v || "").toString().replace(/[^\d.]/g,"");
    var parts = val.split(".");
    if (parts.length > 2) val = parts[0] + "." + parts.slice(1).join("");
    return val;
  }
  function parseAmount(total, base, addon){
    var t = parseFloat(cleanNumber(total));
    if (!isNaN(t) && t > 0) return t;
    var b = parseFloat(cleanNumber(base));  if (isNaN(b)) b = 0;
    var a = parseFloat(cleanNumber(addon)); if (isNaN(a)) a = 0;
    var sum = b + a;
    return sum > 0 ? sum : null;
  }
  function formatCurrency(n){
    if (n == null || isNaN(n)) return "—";
    return (Math.round(n) === n) ? ("$" + n.toFixed(0)) : ("$" + n.toFixed(2));
  }
  function renderAmount(){
    if (!amountDisplay) return;
    var totalAmount = parseAmount(
      totalEl ? totalEl.value : "",
      baseEl ? baseEl.value : "",
      addEl ? addEl.value : ""
    );
    amountDisplay.textContent = formatCurrency(totalAmount);
  }

  // ============================
  // STRIPE STATE
  // ============================
  var stripe = Stripe(STRIPE_PUBLISHABLE_KEY);
  var elements = null;
  var paymentElement = null;
  var elementComplete = false;
  var activeMode = "payment"; // "payment" | "setup"
  var switching = false;

  function resetStripeUI() {
    elementComplete = false;
    payBtn.disabled = true;

    try { if (paymentElement) paymentElement.unmount(); } catch(e) {}
    paymentElement = null;
    elements = null;

    if (paymentMount) paymentMount.innerHTML = "";
  }

  // ============================
  // FLOW CALL HELPER (robust JSON)
  // ============================
  async function postJson(url, payload) {
    const resp = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    const raw = await resp.text();
    let data;
    try { data = JSON.parse(raw); }
    catch { throw new Error("Flow returned invalid JSON: " + (raw || "(empty)")); }

    if (!resp.ok) {
      throw new Error(data.error || data.message || "Flow call failed (HTTP " + resp.status + ")");
    }
    return data;
  }

  // ============================
  // RECURRING PAYLOAD
  // ============================
  function getRecurringPayload(){
    if (!enableRecurring || !enableRecurring.checked) return null;
    return {
      enabled: true,
      frequency: (freqEl ? freqEl.value : "monthly"),
      startDate: (startEl ? startEl.value : ""),
      endDate: (endEl ? endEl.value : "") || null
    };
  }

  // ============================
  // INIT: ONE-OFF PaymentIntent
  // ============================
  async function initPaymentIntent(){
    resetStripeUI();
    activeMode = "payment";
    setStatus("Loading secure payment…", "busy");

    const data = await postJson(FLOW_PAYMENTINTENT_URL, {
      acceptanceId: acceptanceId,
      clientToken: clientToken
    });

    if (!data || !data.clientSecret || data.clientSecret.indexOf("_secret_") === -1) {
      throw new Error("Flow returned an invalid PaymentIntent client secret.");
    }

    elements = stripe.elements({
      clientSecret: data.clientSecret,
      disableLink: true
    });

    paymentElement = elements.create("payment");
    paymentElement.on("change", function(e){
      elementComplete = !!e.complete;
      payBtn.disabled = !elementComplete;
      if (e.error) showError(e.error.message);
      else clearError();
    });

    paymentElement.mount("#payment-element");
    setStatus("Enter your details to continue", "ok");
  }

// ============================
// Date helper
// ============================
function getTodayIso(){
  return new Date().toISOString().split('T')[0];
}

// ============================
// Recurring payload
// ============================
function getRecurringPayload(){
  if(!enableRecurring || !enableRecurring.checked) return null;
  var start = (startEl ? startEl.value.trim() : '') || getTodayIso();
  var end   = (endEl   ? endEl.value.trim()   : '') || null;
  return {
    enabled:   true,
    frequency: (freqEl ? freqEl.value : 'monthly'),
    startDate: start,
    endDate:   end
  };
}

// ============================
// initSetupIntent (updated)
// ============================
async function initSetupIntent(){
  resetStripeUI();
  activeMode = 'setup';
  setStatus('Preparing recurring setup…', 'busy');

  const recurring = getRecurringPayload() || {
    enabled:   true,
    frequency: subFreqLabel.toLowerCase() || 'monthly',
    startDate: getTodayIso(),
    endDate:   null
  };

  const data = await postJson(FLOW_SETUPINTENT_URL, {
    acceptanceId: acceptanceId,
    clientToken:  clientToken,
    recurring:    recurring
  });

  if(!data || !data.clientSecret || data.clientSecret.indexOf('_secret_') === -1){
    throw new Error('Invalid SetupIntent client secret. Got: ' + JSON.stringify(data));
  }

  elements = stripe.elements({
    clientSecret: data.clientSecret,
    disableLink: true
  });

  paymentElement = elements.create('payment');
  paymentElement.on('change', function(e){
    elementComplete = !!e.complete;
    payBtn.disabled = !elementComplete;
    if(e.error) showError(e.error.message);
    else clearError();
  });

  paymentElement.mount('#payment-element');
  setStatus('Enter your details to continue', 'ok');
}

  // ============================
  // SWITCH MODE (checkbox tick)
  // ============================
  if (recurringFields) {
    recurringFields.style.display = (enableRecurring && enableRecurring.checked) ? "block" : "none";
  }

  if (enableRecurring) {
    enableRecurring.addEventListener('change', async function(){
      // Subscription path never uses the checkbox — ignore
      if (isSubscription) return;
      if (switching) return;
      switching = true;
      clearError();
      try {
        if (this.checked) {
          if (recurringFields) recurringFields.style.display = 'block';
          payBtn.textContent = 'Set up recurring payment';
          await initSetupIntent();
        } else {
          if (recurringFields) recurringFields.style.display = 'none';
          payBtn.textContent = 'Pay now';
          await initPaymentIntent();
        }
      } catch(e) {
        setStatus('Unable to load payment', '');
        showError(e.message || 'Unable to load payment.');
      } finally {
        switching = false;
      }
    });
  }

  // ============================
  // If schedule changes after tick, recreate SetupIntent (debounced)
  // NOTE: this will clear card/bank fields (expected).
  // ============================
  var scheduleTimer = null;
  function scheduleChanged(){
    if (!enableRecurring || !enableRecurring.checked) return;
    if (activeMode !== "setup") return;

    clearError();
    setStatus("Schedule changed — refreshing payment setup…", "busy");

    if (scheduleTimer) clearTimeout(scheduleTimer);
    scheduleTimer = setTimeout(function(){
      initSetupIntent().catch(function(e){
        setStatus("Unable to load payment", "");
        showError(e.message || "Unable to load payment.");
      });
    }, 450);
  }

  if (freqEl)  freqEl.addEventListener("change", scheduleChanged);
  if (startEl) startEl.addEventListener("change", scheduleChanged);
  if (endEl)   endEl.addEventListener("change", scheduleChanged);

  // ============================
  // SUBMIT HANDLER (no remount here)
  // ============================
  payBtn.addEventListener("click", async function(){
    clearError();
    payBtn.disabled = true;
    setStatus("Processing…", "busy");

    try {
      if (!elements) throw new Error("Payment form is not ready yet.");
      if (!elementComplete) throw new Error("Please complete your payment details.");

        // Subscription always uses confirmSetup
        // Donation recurring opt-in also uses confirmSetup (existing)
        // One-off uses confirmPayment (existing)

        var returnUrl =
          window.location.origin +
          COMPLETE_URL +
          '?acceptanceid=' + encodeURIComponent(acceptanceId) +
          '&token=' + encodeURIComponent(clientToken);

        if (isSubscription) {
          // Membership subscription — confirm SetupIntent
          // Power Automate picks up from here and creates the Stripe subscription
          const result = await stripe.confirmSetup({
            elements: elements,
            confirmParams: { return_url: returnUrl }
          });
          if (result && result.error) {
            throw new Error(result.error.message || 'Payment method could not be confirmed.');
          }
          return;
        }

        var recurring = getRecurringPayload();

        if (recurring && recurring.enabled) {
          // Donation recurring opt-in (existing behaviour unchanged)
          const result = await stripe.confirmSetup({
            elements: elements,
            confirmParams: { return_url: returnUrl }
          });
          if (result && result.error) {
            throw new Error(result.error.message || 'Setup could not be confirmed.');
          }
          return;
        }

        // One-off donation (existing behaviour unchanged)
        const result = await stripe.confirmPayment({
          elements: elements,
          confirmParams: { return_url: returnUrl }
        });
        if (result && result.error) {
          throw new Error(result.error.message || 'Payment could not be confirmed.');
        }

    } catch (e) {
      setStatus("Ready", "ok");
      payBtn.disabled = !elementComplete;
      showError(e.message || "Payment could not be completed.");
    }
  });

  // ============================
  // BOOTSTRAP
  // ============================
  renderAmount();

(async function boot(){
  try {
    if (isSubscription) {
      // Membership subscription — always SetupIntent, no checkbox
      if (recurringFields) recurringFields.style.display = 'none';
      payBtn.textContent = 'Set up membership';
      await initSetupIntent();
    } else if (enableRecurring && enableRecurring.checked) {
      // Donation recurring opt-in (existing behaviour)
      if (recurringFields) recurringFields.style.display = 'block';
      payBtn.textContent = 'Set up recurring payment';
      await initSetupIntent();
    } else {
      // One-off donation (existing behaviour)
      if (recurringFields) recurringFields.style.display = 'none';
      payBtn.textContent = 'Pay now';
      await initPaymentIntent();
    }
  } catch(e) {
    setStatus('Unable to load payment', '');
    showError(e.message || 'Unable to load payment.');
  }
})();

})();
</script>

  {%- endif -%}

</div>"
}
